def topbar(title):
    return f"""<header class="dashboard-topbar">
    <div style="display:flex;align-items:center;gap:1rem;">
      <button class="mobile-menu-btn" id="mobileMenuBtn"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="18" x2="21" y2="18"/></svg></button>
      <h1 class="dashboard-title">{title}</h1>
    </div>
    <div class="topbar-right"><div class="topbar-avatar" id="topbarAvatar" onclick="window.location.href='404.html'" style="cursor:pointer;">U</div></div>
  </header>"""

def public_page(title, desc, active, body):
    return f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>{title} — Stackly Music School Academy</title>
  <meta name="description" content="{desc}" />
  <link rel="stylesheet" href="css/style.css" />
  <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js"></script>
</head>
<body>
{header(active)}
{body}
<footer class="footer"></footer>
<script src="js/main.js"></script>
<script src="js/animations.js"></script>
</body>
</html>"""

def dash_page(title, active, required_role, body, extra_scripts=''):
    return f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>{title} — Stackly Music School Academy</title>
  <link rel="stylesheet" href="css/style.css" />
  <link rel="stylesheet" href="css/dashboard.css" />
  <script src="js/auth.js"></script>
  <script>document.addEventListener('DOMContentLoaded', () => {{ if (!authProtectRoute('{required_role}')) return; authApplyRBAC(); }});</script>
  {'<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>' if 'chart' in extra_scripts.lower() else ''}
</head>
<body>
{sidebar(active)}
<main class="dashboard-main">
  {topbar(title)}
  <div class="dashboard-content">
    {body}
  </div>
</main>
<div id="toast-container" aria-live="polite"></div>
<script src="js/main.js"></script>
{extra_scripts}
</body>
</html>"""

def save(filename, content):
    path = os.path.join(BASE_DIR, filename)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)

