save("login.html", """<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1.0"/><title>Sign In — Stackly</title><link rel="stylesheet" href="css/style.css"/><link rel="stylesheet" href="css/auth.css"/><script src="js/auth.js"></script></head><body>
<div class="auth-page"><div class="auth-card"><div class="auth-logo"><img src="images/logo-stackly.webp" alt="Stackly"/></div><h2 class="auth-title">Welcome Back</h2><p class="auth-subtitle">Sign in to access your music dashboard</p>
<div class="role-selector" id="roleSelector"><button class="role-option active" data-role="student" onclick="selectRole(this)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>Student</button><button class="role-option" data-role="teacher" onclick="selectRole(this)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87"/><path d="M16 3.13a4 4 0 010 7.75"/></svg>Teacher</button><button class="role-option" data-role="admin" onclick="selectRole(this)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>Admin</button></div>
<form onsubmit="event.preventDefault();handleLogin()"><div class="form-group"><label>Email <span class="required">*</span></label><input type="email" class="form-control" id="loginEmail" placeholder="you@example.com" required/><div class="form-error"></div></div><div class="form-group"><label>Password <span class="required">*</span></label><div class="password-wrapper"><input type="password" class="form-control" id="loginPassword" placeholder="••••••••" required minlength="6"/><button type="button" class="password-toggle"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg></button></div><div class="form-error"></div></div><button type="submit" class="btn btn-warm" style="width:100%;justify-content:center;">Sign In</button></form>
<div class="auth-footer">Don't have an account? <a href="signup.html">Sign up</a></div></div></div>
<script>let selectedRole='student';function selectRole(el){document.querySelectorAll('.role-option').forEach(o=>o.classList.remove('active'));el.classList.add('active');selectedRole=el.dataset.role;}function handleLogin(){const email=document.getElementById('loginEmail').value;const password=document.getElementById('loginPassword').value;const result=authLogin(email,password,selectedRole);if(result.success){window.location.href='dashboard.html';}}</script>
</body></html>""")

save("signup.html", """<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1.0"/><title>Sign Up — Stackly</title><link rel="stylesheet" href="css/style.css"/><link rel="stylesheet" href="css/auth.css"/><script src="js/auth.js"></script></head><body>
<div class="auth-page"><div class="auth-card"><div class="auth-logo"><img src="images/logo-stackly.webp" alt="Stackly"/></div><h2 class="auth-title">Create Account</h2><p class="auth-subtitle">Join Stackly Music School Academy today</p>
<form onsubmit="event.preventDefault();handleSignup()"><div class="form-row"><div class="form-group"><label>First Name <span class="required">*</span></label><input type="text" class="form-control" id="signupFirst" placeholder="John" required/></div><div class="form-group"><label>Last Name <span class="required">*</span></label><input type="text" class="form-control" id="signupLast" placeholder="Doe" required/></div></div>
<div class="form-group"><label>Email <span class="required">*</span></label><input type="email" class="form-control" id="signupEmail" placeholder="john@example.com" required/></div>
<div class="form-group"><label>Phone <span class="required">*</span></label><input type="tel" class="form-control" id="signupPhone" placeholder="9876543210" required/></div>
<div class="form-group"><label>Password <span class="required">*</span></label><div class="password-wrapper"><input type="password" class="form-control" id="signupPassword" placeholder="Minimum 6 characters" required minlength="6"/></div></div>
<button type="submit" class="btn btn-warm" style="width:100%;justify-content:center;">Create Account</button></form>
<div class="auth-footer">Already have an account? <a href="login.html">Sign in</a></div></div></div>
<script>function handleSignup(){const name=document.getElementById('signupFirst').value+' '+document.getElementById('signupLast').value;const email=document.getElementById('signupEmail').value;const password=document.getElementById('signupPassword').value;const phone=document.getElementById('signupPhone').value;const result=authSignup(name,email,password,phone,'student');if(result.success){localStorage.setItem('stackly_music_auth',JSON.stringify(result.user));window.location.href='dashboard.html';}}</script>
<script src="js/main.js"></script>
</body></html>""")

